import json, numpy as np, collections
rows = json.load(open('/app/cache/scan_data.json'))
RZ = {'A':80.,'B':200.,'C':320.}
def zones_from_scene(scene, N, change_trial=30):
    for a in 'ABC':
        for b in 'ABC':
            if a==b: continue
            if f'{a}_to' in scene and scene[-1]==b:
                return np.array([a]*min(change_trial,N) + [b]*max(0,N-change_trial))
    for x in 'ABC':
        if scene.endswith('Location'+x):
            return np.array([x]*N)
    raise ValueError(scene)
bad = 0
for r in rows:
    scene = r['identifier'].split('/')[-1]
    N = r['ntrials']
    z = zones_from_scene(scene, N)
    emp = np.array(r['rz_starts'])
    ok = np.isnan(emp) | (np.abs(emp - np.array([RZ[x] for x in z])) < 3)
    # allow rz onset later than start if mouse entered zone (should be >= start)
    ok2 = np.isnan(emp) | ((emp >= np.array([RZ[x] for x in z])-1) & (emp < np.array([RZ[x] for x in z])+50))
    if not ok2.all():
        bad += 1
        idx = np.where(~ok2)[0]
        print('MISMATCH', r['file'], scene, 'trials', idx[:10], emp[idx][:10], z[idx][:10])
print('sessions with mismatch:', bad, '/', len(rows))
